/** Files are stored under `spaces/{s}/assets/{id}/`: the upload as `original`, generated renditions next to it. */
export { assetFilesPrefix as assetPrefix } from '../../../shared/data-rules/storage-deletions.js';

export const originalKey = (spaceId: string, assetId: string): string => `spaces/${spaceId}/assets/${assetId}/original`;
/** Generated bytes are cached next to the original and deleted with it. Keyed by what defines the bytes. */
export const renditionKey = (spaceId: string, assetId: string, etagSuffix: string, thumbnail: boolean): string =>
  `spaces/${spaceId}/assets/${assetId}/renditions/${etagSuffix || 'orig'}${thumbnail ? '-thumbnail' : ''}`;
